//! Ultimate Equipment (UE) shared equipment tables -- full in-scope corpus
//! coverage. SD28-E25 slice 1, mirroring `ultimate_intrigue::equipment_tables`'s
//! own established shape exactly (own `EquipmentCategory` enum, description
//! joining the corpus `DESC:` and `SPROP:` tokens when both are present --
//! unlike ARG/UI, this corpus carries a real `DESC:` token on some records
//! alongside `SPROP:` on others, occasionally both on the same record).
//!
//! **UE is Paizo's own equipment compendium book -- it republishes items
//! from earlier books alongside new content, and those republished items
//! are deliberately excluded here, not ingested a second time.** Re-derived
//! against every OTHER book's real RUNTIME key set (a scratch #[test]
//! dump, not a source grep -- CRB/APG/ACG/beastiary1's tables are not
//! literal `key: "..."` source text, and a first-pass source-grep-only
//! check silently missed all of them, caught by
//! `keys_do_not_collide_across_books_and_crbs_own_duplicates_are_pinned`
//! before it shipped, per `decisions.md §39`'s `already_ingested_keys()`
//! precedent for exactly this situation): 65
//! colliding keys (55 equipment + 10 equipmods). Spot-checked
//! one: `Dogslicer` is confirmed to be ARG's own goblin weapon
//! (`arg_equip_arms_armor.lst`), byte-identical stats -- a genuine
//! republish, not a coincidental name clash. Excluding all of them is the
//! same non-regression discipline `§39` established for APG's Dwarf ~
//! Ancient Enmity collision with ARG: shipping the older or duplicate
//! copy under a new book's label would be either a stub-shaped no-op or
//! a silent regression, neither of which this table does.
//!
//! **92 of the corpus's declared 1,424 equipment rows are `.COPY=` rows
//! that declare a genuinely distinct new item** (a masterwork or size
//! variant -- e.g. `Harpsichord (Base).COPY=Musical Instrument,
//! Masterwork Harpsichord`, `Barding (Haramaki).COPY=Barding
//! (Haramaki/Large)`), not a mere re-listing the way `ui_equipmods.lst`'s
//! `VISIBLE:NO` alias rows were -- confirmed by re-deriving against
//! `docs/work-inventory.json`'s own 1,424: the base non-`.COPY=` parse
//! alone found only 1,332, and the `.COPY=` rows account for exactly the
//! missing 92 (24 general + 68 arms/armor). These rows rarely carry
//! their own `COST:`/`WT:` token (inherited via `BASEITEM:`, which this
//! table does not resolve), so `cost_gp`/`weight_lbs` are honestly
//! `None` for most of them rather than looked up and fabricated.
//!
//! Record coverage: every real, active (non-`.MOD`), non-cross-book-collision
//! record across `ue_equip_general.lst`, `ue_equip_arms_armor.lst`,
//! `ue_equip_magic_items.lst` -- 1369 equipment records
//! total (of the corpus's declared 1,424, after excluding 55
//! cross-book republished items) -- and `ue_equipmods.lst` (180
//! equipment-modifier records, of the corpus's declared 190, after
//! excluding 10 cross-book republished modifiers; this
//! book's own `work-inventory.json` `equipment_modifier` kind, not
//! counted in the 1369 above).
//!
//! `key` is the corpus `KEY:` token when the row carries one, else its
//! display `name`. `cost_gp`/`weight_lbs` are `None` when the corpus token
//! is absent or a non-numeric PCGen formula this table does not evaluate --
//! never a fabricated flat number for a formula cost.

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum EquipmentCategory {
    General,
    ArmsArmor,
    MagicItems,
    Equipmods,
}

impl EquipmentCategory {
    pub const ALL: &'static [EquipmentCategory] = &[
        EquipmentCategory::General,
        EquipmentCategory::ArmsArmor,
        EquipmentCategory::MagicItems,
        EquipmentCategory::Equipmods,
    ];
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct EquipmentTableEntry {
    pub key: &'static str,
    pub category: EquipmentCategory,
    pub name: &'static str,
    /// Cost in gold pieces from the corpus `COST:` token. `None` when the
    /// token is absent or a non-numeric PCGen formula this table does not
    /// evaluate.
    pub cost_gp: Option<f64>,
    /// Weight in pounds from the corpus `WT:` token. `None` when the
    /// corpus record carries no `WT:` token (true for every
    /// `ue_equipmods.lst` record -- equipment *modifiers* carry no
    /// independent weight, matching every other book's own established
    /// finding).
    pub weight_lbs: Option<f64>,
    /// Descriptive text: the corpus `DESC:` token, the `SPROP:` token, or
    /// both joined with a space when a record carries both. `None` only
    /// when the corpus record has neither.
    pub description: Option<&'static str>,
}

